const Image& symbol(unsigned id,uint32_t ms,bool winning) { using phoenix::Symbol; switch(static_cast<Symbol>(id)) {
case Symbol::Nine: return (winning ? *nineWinFrames[(ms/125)%10] : nine);
case Symbol::Ten: return (winning ? *tenWinFrames[(ms/125)%8] : ten);
case Symbol::Jack: return jack;
case Symbol::Queen: return queen;
case Symbol::King: return king;
case Symbol::Bell: return (winning ? bell_art::frame(ms) : bell_art::idle());
case Symbol::Abacus: return (winning ? abacusAnimation(ms) : abacus);
case Symbol::Book: return (winning ? bookAnimation(ms) : book);
case Symbol::Candle: return *candleFrames[(ms/125)%16];
case Symbol::Wild: return (winning ? wildAnimation(ms) : wild);
case Symbol::Scatter: return (winning && ms>=2000 ? *scatterFrames[((ms-2000)/40)%100] : scatter);
case Symbol::Phoenix: return phoenix_art::frame(ms);
default:return background;
}}
